// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EmergencyOracleFactory c;

    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function _run(bool makeAdmin, string memory description) internal {
        bool beforeIsAdmin;
        try c.isAdmin(address(this)) returns (bool __r) { beforeIsAdmin = __r; } catch { return; }
        bool reverted;
        address oracleAddress = address(0);
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == (!beforeIsAdmin));
    }

    function testFuzz_run(bool makeAdmin, string memory description) public {
        _run(makeAdmin, description);
    }

    receive() external payable {}
}
